PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT (?a_wr AS ?wr)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma lila:hasPOS lila:noun .
    ?a_lemma ontolex:writtenRep ?a_wr .
    FILTER(REGEX(STR(?a_wr), "ezza$")) .
  }
  GRAPH <http://liita.it/data> { ?a_lemma a ?f_featLemmaType . ?a_lemma lila:hasGender ?f_gender . FILTER(?f_gender = lila:feminine) OPTIONAL { ?a_lemma lila:hasDegree ?f_degree . } OPTIONAL { ?a_lemma lila:hasInflectionType ?f_inflectionType . } }
}

