PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:float(?s_polarityValue)) AS ?avgValue)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma lila:hasPOS lila:adverb .
    ?a_lemma ontolex:writtenRep ?a_wr .
  }
  ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
               marl:hasPolarity ?s_polarity ;
               marl:hasPolarityValue ?s_polarityValue .
  BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT (?verbCount AS ?count)
WHERE {
  { SELECT (COUNT(DISTINCT ?a_lemma) AS ?verbCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
        ?a_lemma a ?a_lemmaType .
        ?a_lemma lila:hasPOS lila:verb .
        ?a_lemma ontolex:writtenRep ?a_wr .
      }
      ?t_itToParEntry ontolex:canonicalForm ?a_lemma ;
                   vartrans:translatableAs ?t_parEntry .
      ?t_parEntry ontolex:canonicalForm ?t_parLemma .
      ?t_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
               ontolex:writtenRep ?t_parWR .
    }
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT (?p_pos AS ?pos) ?lemmaCount
WHERE {
  { SELECT ?p_pos (COUNT(DISTINCT ?a_lemma) AS ?lemmaCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
        ?a_lemma a ?a_lemmaType .
        ?a_lemma ontolex:writtenRep ?a_wr .
      }
      ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
      ?e_elitaLemma elita:HasEmotion ?e_emotion .
      VALUES ?e_emotion { elita:Paura }
      ?e_emotion rdfs:label ?e_emotionLabel .
      GRAPH <http://liita.it/data> {
        ?a_lemma lila:hasPOS ?p_pos .
      }
    }
    GROUP BY ?p_pos
  }
  { SELECT (MAX(?lemmaCount) AS ?maxCount) WHERE {
      { SELECT ?p2_pos (COUNT(DISTINCT ?a2_lemma) AS ?lemmaCount) WHERE {
          GRAPH <http://liita.it/data> {
            VALUES ?a2_lemmaType { lila:Lemma lila:Hypolemma }
            ?a2_lemma a ?a2_lemmaType .
            ?a2_lemma ontolex:writtenRep ?a2_wr .
          }
          ?e2_elitaLemma ontolex:canonicalForm ?a2_lemma .
          ?e2_elitaLemma elita:HasEmotion ?e2_emotion .
          VALUES ?e2_emotion { elita:Paura }
          ?e2_emotion rdfs:label ?e2_emotionLabel .
          GRAPH <http://liita.it/data> {
            ?a2_lemma lila:hasPOS ?p2_pos .
          }
        }
        GROUP BY ?p2_pos
      }
    }
  }
  FILTER(?lemmaCount >= ?maxCount)
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (?a_writtenRep AS ?writtenRep) (COUNT(DISTINCT ?a_sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?a_word ontolex:canonicalForm [ ontolex:writtenRep ?a_writtenRep ] ;
          ontolex:sense ?a_sense .
    FILTER(STR(?a_writtenRep) = "corrente") .
  }
}
GROUP BY ?a_writtenRep
ORDER BY DESC(?count)

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (?a_writtenRep AS ?writtenRep) (COUNT(DISTINCT ?a_sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?a_lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?a_writtenRep ] .
    ?a_lexicalEntry ontolex:sense ?a_sense .
    FILTER(regex(str(?a_writtenRep), "^(rete|carta|lettera)$", "i")) .
  }
}
GROUP BY ?a_writtenRep
ORDER BY DESC(?count)

