            ?ap1b_word ontolex:sense ?sp1b_anySense .
          }
        }
        GROUP BY ?ap1b_word
        HAVING (COUNT(DISTINCT ?sp1b_anySense) > 1)
      }
      { SELECT ?ap1b_word (COUNT(DISTINCT ?ep1b_emotion) AS ?emo2b) WHERE {
          ?ap1b_word ontolex:canonicalForm ?jp1b_liitaLemma .
          GRAPH <http://liita.it/data> { ?jp1b_liitaLemma a ?jp1b_liitaLemmaType ; ontolex:writtenRep ?jp1b_liitaWR . FILTER(?jp1b_liitaLemmaType IN (lila:Lemma, lila:Hypolemma)) }
          ?ep1b_elitaLemma ontolex:canonicalForm ?jp1b_liitaLemma .
          ?ep1b_elitaLemma elita:HasEmotion ?ep1b_emotion .
          ?ep1b_emotion rdfs:label ?ep1b_emotionLabel .
        }
        GROUP BY ?ap1b_word
        HAVING (COUNT(DISTINCT ?ep1b_emotion) >= 1)
      }
    }
  }
}
